def dfs_iterative(graph, start):
    visited = set()
    order = []
    stack = [start]
    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        order.append(node)
        for neighbor in reversed(graph.get(node, [])):
            if neighbor not in visited:
                stack.append(neighbor)
    return order

# Example: dfs_iterative({0:[1,2],1:[0,3],2:[0],3:[1]}, 0) -> [0, 1, 3, 2]
# Time: O(V+E), Space: O(V). Explicit stack DFS pushing neighbors reversed for order.

from collections import deque

def shortest_path(graph, start, target):
    if start == target:
        return [start]
    visited = set([start])
    q = deque([(start, [start])])
    while q:
        node, path = q.popleft()
        for neighbor in graph.get(node, []):
            if neighbor == target:
                return path + [neighbor]
            if neighbor not in visited:
                visited.add(neighbor)
                q.append((neighbor, path + [neighbor]))
    return []

# Example: shortest_path({0:[1,2],1:[2],2:[0,3],3:[]}, 0, 3) -> [0, 2, 3]
# Time: O(V+E), Space: O(V). BFS stores the path with each queue entry.

from collections import deque

def is_bipartite(n, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    color = [-1] * n
    for start in range(n):
        if color[start] != -1:
            continue
        color[start] = 0
        q = deque([start])
        while q:
            node = q.popleft()
            for neighbor in graph[node]:
                if color[neighbor] == -1:
                    color[neighbor] = 1 - color[node]
                    q.append(neighbor)
                elif color[neighbor] == color[node]:
                    return False
    return True

# Example: is_bipartite(4, [[0,1],[1,2],[2,3],[3,0]]) -> True
# Time: O(V+E), Space: O(V). BFS 2-coloring across all connected components.

def count_components(n, edges):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    for u, v in edges:
        union(u, v)
    roots = set(find(i) for i in range(n))
    return len(roots)

# Example: count_components(6, [[0,1],[2,3]]) -> 4
# Time: O(V+E) nearly O(alpha(V)) per op, Space: O(V). Union-Find with path compression.

def num_islands(grid):
    if not grid:
        return 0
    m, n = len(grid), len(grid[0])
    count = 0
    def sink(r, c):
        if r < 0 or r >= m or c < 0 or c >= n or grid[r][c] != '1':
            return
        grid[r][c] = '0'
        sink(r + 1, c)
        sink(r - 1, c)
        sink(r, c + 1)
        sink(r, c - 1)
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1':
                count += 1
                sink(i, j)
    return count

# Example: num_islands([['1','1','0'],['1','1','0'],['0','0','1']]) -> 2
# Time: O(m*n), Space: O(m*n) worst recursion. DFS flood-fill each new island.

def has_cycle_directed(n, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
    state = [0] * n
    def dfs(node):
        state[node] = 1
        for neighbor in graph[node]:
            if state[neighbor] == 1:
                return True
            if state[neighbor] == 0 and dfs(neighbor):
                return True
        state[node] = 2
        return False
    for i in range(n):
        if state[i] == 0 and dfs(i):
            return True
    return False

# Example: has_cycle_directed(3, [[0,1],[1,2],[2,0]]) -> True
# Time: O(V+E), Space: O(V). Three-state (unvisited/visiting/visited) DFS cycle check.

def has_cycle_undirected(n, edges):
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    for u, v in edges:
        ru, rv = find(u), find(v)
        if ru == rv:
            return True
        if rank[ru] < rank[rv]:
            parent[ru] = rv
        elif rank[ru] > rank[rv]:
            parent[rv] = ru
        else:
            parent[rv] = ru
            rank[ru] += 1
    return False

# Example: has_cycle_undirected(3, [[0,1],[1,2],[2,0]]) -> True
# Time: O(E * alpha(V)), Space: O(V). Union by rank; merging already-united nodes means a cycle.

def bellman_ford(n, edges, source):
    dist = [float('inf')] * n
    dist[source] = 0
    for _ in range(n - 1):
        updated = False
        for u, v, w in edges:
            if dist[u] != float('inf') and dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                updated = True
        if not updated:
            break
    for u, v, w in edges:
        if dist[u] != float('inf') and dist[u] + w < dist[v]:
            return None
    return dist

# Example: bellman_ford(5, [[0,1,4],[0,2,1],[2,1,2],[1,3,1],[2,3,5],[3,4,3]], 0) -> [0,3,1,4,7]
# Time: O(V*E), Space: O(V). Relax all edges V-1 times; one more pass detects negative cycles (returns None).

def min_path_sum(grid):
    m, n = len(grid), len(grid[0])
    dp = [0] * n
    dp[0] = grid[0][0]
    for j in range(1, n):
        dp[j] = dp[j-1] + grid[0][j]
    for i in range(1, m):
        dp[0] += grid[i][0]
        for j in range(1, n):
            dp[j] = min(dp[j], dp[j-1]) + grid[i][j]
    return dp[n-1]

# Example: min_path_sum([[1,3,1],[1,5,1],[4,2,1]]) -> 7
# Time: O(m*n), Space: O(n). Rolling 1D DP row of best costs to reach each column.

def find_cheapest_price(n, flights, src, dst, k):
    INF = float('inf')
    dist = [INF] * n
    dist[src] = 0
    for _ in range(k + 1):
        temp = dist[:]
        for u, v, w in flights:
            if dist[u] != INF and dist[u] + w < temp[v]:
                temp[v] = dist[u] + w
        dist = temp
    return dist[dst] if dist[dst] != INF else -1

# Example: find_cheapest_price(4, [[0,1,100],[1,2,100],[2,0,100],[1,3,600],[2,3,200]], 0, 3, 1) -> 700
# Time: O((k+1)*E), Space: O(V). Bellman-Ford limited to k+1 edge relaxations.

def merge_intervals(intervals):
    intervals.sort()
    merged = []
    for start, end in intervals:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return merged

# Example: merge_intervals([[1,3],[2,6],[8,10],[15,18]]) -> [[1,6],[8,10],[15,18]]
