def unique_paths_with_obstacles(grid):
    m, n = len(grid), len(grid[0])
    if grid[0][0] == '*' or grid[m-1][n-1] == '*':
        return 0
    dp = [0] * n
    dp[0] = 1
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '*':
                dp[j] = 0
            elif j > 0:
                dp[j] += dp[j-1]
    return dp[n-1]

# Example: unique_paths_with_obstacles([['.','*','.'],['.','.','.'],['*','.','.']]) -> 2
