from collections import deque

def valid_path(n, edges, source, destination):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    visited = set([source])
    q = deque([source])
    while q:
        node = q.popleft()
        if node == destination:
            return True
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                q.append(neighbor)
    return False

# Example: valid_path(3, [[0,1],[1,2],[0,2]], 0, 2) -> True
# Time: O(V+E), Space: O(V). Simple undirected BFS reachability.

def make_connected(n, connections):
    if len(connections) < n - 1:
        return -1
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    components = n
    for u, v in connections:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv
            components -= 1
    return components - 1

# Example: make_connected(6, [[1,2],[3,4]]) -> 3
# Time: O(E * alpha(V)), Space: O(V). Union-Find: need at least n-1 cables; leftover cables bridge components.

def articulation_points(n, edges):
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    disc = [-1] * n
    low = [0] * n
    parent = [-1] * n
    ap = set()
    time = 0
    def dfs(u):
        nonlocal time
        disc[u] = low[u] = time
        time += 1
        children = 0
        for v in graph[u]:
            if disc[v] == -1:
                parent[v] = u
                children += 1
                dfs(v)
                low[u] = min(low[u], low[v])
                if parent[u] == -1 and children > 1:
                    ap.add(u)
                if parent[u] != -1 and low[v] >= disc[u]:
                    ap.add(u)
            elif v != parent[u]:
                low[u] = min(low[u], disc[v])
    for i in range(n):
        if disc[i] == -1:
            dfs(i)
    return sorted(ap)

# Example: articulation_points(5, [[0,1],[1,2],[2,3],[3,0],[1,4]]) -> [1]
# Time: O(V+E), Space: O(V). Tarjan's low-link DFS finds cut vertices.
